/**
 * Объявления для импортов, которые понимает только сборщик приложения.
 *
 * Пакет собирается `tsc`, а ассеты (wasm-модули движка) подставляет Vite:
 * суффикс `?url` — его соглашение, и `tsc` о нём знать не может. Объявление
 * здесь описывает не поведение, а договор с бандлером: по такому импорту
 * приходит адрес файла, а не его содержимое.
 *
 * Так же устроен и сам движок: `@betteroffice/docx` объявляет свои wasm
 * через `new URL('./...wasm', import.meta.url)`, и раскладывает их тоже
 * сборщик. Отдельного каталога ассетов здесь нет: адреса считает бандлер.
 */
declare module '*?url' {
  const url: string;

  export default url;
}
